import type { StorageProvider, SavedDoc } from '@atlantis/shared';
import { supabase } from './supabase';

export const supabaseProvider: StorageProvider = {
  async saveDoc(appId, name, content) {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) throw new Error('Not authenticated');
    const { data, error } = await supabase
      .from('documents')
      .insert({ user_id: user.id, app_id: appId, name, content, saved_at: new Date().toISOString() })
      .select('id')
      .single();
    if (error) throw error;
    return data.id as string;
  },

  async updateDoc(id, name, content) {
    const { error } = await supabase
      .from('documents')
      .update({ name, content, saved_at: new Date().toISOString() })
      .eq('id', id);
    if (error) throw error;
  },

  async listDocs(appId) {
    const { data, error } = await supabase
      .from('documents')
      .select('id, app_id, name, content, saved_at')
      .eq('app_id', appId)
      .order('saved_at', { ascending: false });
    if (error) throw error;
    return (data ?? []).map((d) => ({
      id:      d.id as string,
      appId:   d.app_id as string,
      name:    d.name as string,
      content: d.content as string,
      savedAt: new Date(d.saved_at as string).getTime(),
    })) as SavedDoc[];
  },

  async deleteDoc(id) {
    const { error } = await supabase.from('documents').delete().eq('id', id);
    if (error) throw error;
  },

  async putSetting(key, value) {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return;
    const { error } = await supabase
      .from('settings')
      .upsert({ user_id: user.id, key, value }, { onConflict: 'user_id,key' });
    if (error) throw error;
  },

  async getSetting(key) {
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return null;
    const { data, error } = await supabase
      .from('settings')
      .select('value')
      .eq('key', key)
      .single();
    if (error) return null;
    return data?.value ?? null;
  },
};
