import { getSetting, putSetting } from '@atlantis/shared';

const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

interface CacheEntry<T> {
  data: T;
  cachedAt: number;
}

/**
 * Fetch with a 5-minute IndexedDB cache.
 * Returns cached data immediately if fresh; fetches otherwise.
 */
export async function cachedFetch<T>(url: string, cacheKey: string): Promise<T | null> {
  const raw = await getSetting(`widget-cache:${cacheKey}`);
  if (raw) {
    try {
      const entry: CacheEntry<T> = JSON.parse(raw);
      if (Date.now() - entry.cachedAt < CACHE_TTL) return entry.data;
    } catch { /* corrupted — refetch */ }
  }

  try {
    const res = await fetch(url);
    if (!res.ok) return null;
    const data: T = await res.json();
    const entry: CacheEntry<T> = { data, cachedAt: Date.now() };
    putSetting(`widget-cache:${cacheKey}`, JSON.stringify(entry));
    return data;
  } catch {
    return null;
  }
}
